(() => {
const esc=escapeHtml;
const mvpLeaders=[...players].filter(p=>Number(p.mvps)>0).sort((a,b)=>Number(b.mvps)-Number(a.mvps)||Number(b.titles||0)-Number(a.titles||0)).slice(0,3);
document.querySelector('#ranking').innerHTML=`<div class="section-head"><h2>Legado em números</h2></div><span class="small-label">MVPs · HALL OF FAME</span>${mvpLeaders.map((p,i)=>`<button class="rank-row mvp-leader" data-player="${players.indexOf(p)}"><b>${String(i+1).padStart(2,'0')}</b><span class="avatar">${esc(p.name[0])}</span><strong>${esc(p.name)}<small>${esc(p.label)}</small></strong><em>${esc(p.mvps)}</em></button>`).join('')}<p>Os três jogadores com mais MVPs registrados no Hall of Fame.</p><a class="full-link" href="#acervo/hall-of-fame">Ver Hall of Fame completo ↗</a>`;
const isMajorTitle=title=>/[Ⓜ🅼]/u.test(title);
const cup='<svg viewBox="0 0 32 38" aria-hidden="true"><path d="M8 3h16v12c0 6-4 10-8 10S8 21 8 15V3Zm0 3H3v6c0 6 4 8 8 8M24 6h5v6c0 6-4 8-8 8M16 25v7M9 34h14" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/><path d="m16 8 1.5 3 3.5.5-2.5 2.5.5 3.5-3-1.5-3 1.5.5-3.5-2.5-2.5 3.5-.5Z" fill="currentColor"/></svg>';
function stats(p){
 const text=p.text,major=text.match(/(?:-?\s*)(\d+)\s*x?\s*MAJOR CHAMPION/i)?.[1]||text.match(/x\s*(\d+)\s*MAJOR CHAMPION/i)?.[1];
 const teams=text.match(/TEAMS\s*\n\s*\[([^\]]+)\]/i)?.[1]?.trim().split(/[\s,]+/).filter(Boolean)||[];
 const rankings=[];const prefix=text.split(/RECORDES|PREMIAÇÕES|TEAMS|PRINCIPAIS/i)[0];
 for(const match of prefix.matchAll(/TOP\s*(\d+)\s*(?:em\s*)?((?:\(20\d{2}\)\s*)+)/gi))for(const y of match[2].matchAll(/20\d{2}/g))rankings.push({rank:Number(match[1]),year:Number(y[0])});
 for(const match of prefix.matchAll(/#(\d+)\s+(20\d{2})/g))rankings.push({rank:Number(match[1]),year:Number(match[2])});
 const rankKey=value=>normalizeText(value).replace(/0/g,'o').replace(/[^a-z0-9]/g,'');
 for(const [year,entries] of Object.entries(window.RANKS_PLAYER_RANKINGS||{})){const entry=entries.find(e=>rankKey(e.name)===rankKey(p.name));if(entry)rankings.push({year:Number(year),rank:entry.rank});}
 const verified=window.HBSTV?.person(p.name)?.rankings;
 const unique=(verified?verified.map(r=>({year:r.year,rank:r.rank})):[...new Map(rankings.map(r=>[r.year,r])).values()]).sort((a,b)=>b.year-a.year);
 const marker=text.search(/PRINCIPAIS T[ÍI]TULOS/i);const titles=marker<0?[]:text.slice(marker).split(/🥇/).slice(1).flatMap(s=>s.split('\n')).map(s=>s.trim()).filter(s=>s&&/20\d{2}/.test(s));
 return {major,teams,rankings:unique,titles,retired:/APOSENTADO/i.test(p.full),realName:p.full.replace(/(?:´´|“|”|"|''|‘)[^´“”"‘]+?(?:´´|“|”|"|''|‘)/g,'').replace(/\[APOSENTADO\]/gi,'').trim(),best:unique.length?Math.min(...unique.map(r=>r.rank)):null};
}
function registeredZdrEvps(p){if(p.name!=='ZDR')return '';const count=p.text.match(/(?:^|\n)-?(\d+)\s*EVPs\b/i)?.[1]||'0';return `<div><dt>EVPs registrados</dt><dd>${esc(count)}</dd></div>`;}
function identity(p,s){return `<div class="hof-identity"><div class="hof-portrait" aria-label="Avatar de ${esc(p.name)}"><span class="hof-player-label">JOGADOR</span><span class="hof-monogram">${esc(p.name.slice(0,2).toUpperCase())}</span><span class="hof-portrait-footer">HALL OF FAME<br><b>HBSTV.ORG</b></span></div><div class="hof-bio"><span class="eyebrow">${esc(p.label)}</span><h2>${esc(p.name)}</h2><p class="hof-real-name">${esc(s.realName)}</p><dl class="hof-facts"><div><dt>Status no acervo</dt><dd>${s.retired?'Aposentado':'EM ATIVIDADE'}</dd></div><div><dt>MVPs registrados</dt><dd>${Number(p.mvps)>0?esc(p.mvps):'NO MVP WIN'}</dd></div>${registeredZdrEvps(p)}<div><dt>Títulos principais</dt><dd>${p.titles?esc(p.titles):'Não informado'}</dd></div><div><dt>Melhor posição anual</dt><dd>${s.best?'#'+s.best+' — '+new Intl.ListFormat('pt-BR',{style:'long',type:'conjunction'}).format(s.rankings.filter(r=>r.rank===s.best).map(r=>r.year).sort((a,b)=>a-b).map(String)):'Não informada'}</dd></div>${window.renderPlayerAnnualFacts?.(s.rankings)||''}<div><dt>Conquistas em Majors</dt><dd>${s.major?`<span class="hof-major-badge">${cup}${esc(s.major)} ${Number(s.major)===1?'Major conquistado':'Majors conquistados'}</span>`:'<span class="hof-no-major">NO MAJOR WIN</span>'}</dd></div></dl></div></div>`;}
window.showPlayerProfile=p=>{
 if(p.registeredOnly)return window.showRegisteredPlayerProfile(p.name);
 const s=stats(p);document.querySelector('#detail').classList.add('profile-dialog');
 const awards=window.getPlayerAwards?.(p)||[];const awardCards=awards.length?awards.map(a=>`<div class="hof-award-card"><span class="hof-award-icon">${cup}</span><div><strong>${a.count}× ${esc(a.category)}</strong><span>${esc(new Intl.ListFormat('pt-BR',{style:'long',type:'conjunction'}).format(a.years.map(String)))}</span></div></div>`).join(''):'<p class="hof-empty">Premiações individuais não informadas no acervo.</p>';
 const ranking=s.rankings.length?s.rankings.map(r=>`<span class="hof-rank-chip"><b>#${r.rank}</b><small>${r.year}</small></span>`).join(''):'<p class="hof-empty">Posições anuais não informadas no registro.</p>';

 showDetail(`<div class="hof-profile">${identity(p,s)}<div class="hof-metrics"><div><b>${p.mvps||'—'}</b><span>MVPs</span></div><div><b>${p.titles||'—'}</b><span>TÍTULOS PRINCIPAIS</span></div><div><b>${s.major||'0'}</b><span>TÍTULOS DE MAJOR</span></div></div><section class="hof-section hof-individual-awards"><div class="hof-section-title"><h3>Awards individuais</h3><span>CATEGORIAS E ANOS</span></div><div class="hof-award-grid">${awardCards}</div></section>${window.renderDocumentedPlayerAwards?.(window.HBSTV?.person(p.name))||''}${window.renderPlayerTitleCards(window.HBSTV?.person(p.name),s.titles)}<section class="hof-section"><div class="hof-section-title"><h3>Top 20 · Histórico anual</h3></div><div class="hof-rankings">${ranking}</div></section>${window.renderPlayerTeamCards(window.HBSTV?.person(p.name),s.teams)}${s.titles.length?`<details class="hof-details"><summary>Ver todos os títulos (${s.titles.length})</summary><ol class="hof-title-list">${s.titles.map(t=>`<li class="${isMajorTitle(t)?'is-major-title':''}">${window.renderOrganizationEmblem?.(t)||cup}<span>${esc(t)}</span>${isMajorTitle(t)?'<b class="hof-major-list-tag">MAJOR</b>':''}</li>`).join('')}</ol></details>`:''}<details class="hof-details"><summary>Registro completo · Premiações e recordes</summary><div class="hof-source-record">${fullRecord(p.blocks)}</div></details><p class="hof-source-note">Dados do Hall of Fame original. As equipes são o histórico da carreira. Foto, idade e premiação em dinheiro não constam no acervo.</p></div>`);
};
window.renderHallSection=blocks=>{const heading=blocks.find(b=>b.type==='heading'&&b.level===4)?.text;const p=players.find(p=>p.full===heading);if(!p)return '';const s=stats(p);return `<div class="hof-collection-profile">${identity(p,s)}<button class="hof-open-profile" data-hof-profile="${players.indexOf(p)}">Ver perfil completo · Conquistas e recordes ↗</button></div>`;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-hof-profile]');if(b)window.showPlayerProfile(players[Number(b.dataset.hofProfile)]);});
document.querySelector('#detail').addEventListener('close',()=>document.querySelector('#detail').classList.remove('profile-dialog'));
})();
